{"title":"每月存钱算一算","note":"月存、年化、年数三个滑块","html":"<style>
  .row{display:flex;gap:10px;align-items:center;margin:6px 0;font-size:var(--font-text-sm-size);color:var(--color-text-secondary)}
  input[type=range]{flex:1;accent-color:var(--color-text-primary)}
  .out{display:flex;align-items:baseline;gap:10px;margin:12px 0 8px}
  .big{font-size:var(--font-heading-lg-size);font-weight:var(--font-weight-semibold);font-variant-numeric:tabular-nums}
  .sub{color:var(--color-text-secondary);font-size:var(--font-text-sm-size)}
  button{font:inherit;font-size:var(--font-text-sm-size);color:var(--color-text-primary);background:var(--color-background-primary);border:1px solid var(--color-border-secondary);border-radius:var(--border-radius-sm);padding:4px 12px;cursor:pointer}
  .tall{margin-top:12px;height:620px;border-radius:var(--border-radius-md);background:repeating-linear-gradient(0deg,var(--color-background-secondary) 0 48px,transparent 48px 96px)}
</style>
<div class="row">每月存<input id="m" type="range" min="500" max="10000" step="500" value="3000"><b id="mv"></b></div>
<div class="out"><span class="big" id="total"></span><span class="sub" id="gain"></span></div>
<button id="label" type="button">换个说法</button>
<button id="save" type="button" style="margin-top:10px">按这个存</button>
<script>document.getElementById("save").addEventListener("click", function () { aios.send("按这个存：每月 3000"); });</script>
<div class="tall" id="tall"></div>
<script>
  var m = document.getElementById('m');
  function money(v) { return '¥' + Math.round(v).toLocaleString('zh-CN'); }
  function draw() {
    var v = +m.value;
    document.getElementById('mv').textContent = money(v);
    document.getElementById('total').textContent = money(v * 120 * 1.05);
    document.getElementById('gain').textContent = '本金 ' + money(v * 120);
  }
  m.addEventListener('input', draw);
  draw();
  document.getElementById('label').addEventListener('click', function () { this.textContent = '已经换了'; });
</script>"}

